function friendlyStatus(v){return String(v||'').replace(/^(CM|LM|UPM|RR)_/,'').replaceAll('_',' ').toLowerCase().replace(/^./,x=>x.toUpperCase())}
function quantityText(c){const unit=String(c.quantity_unit||c.unit_label||'PCS').toUpperCase(),n=Number(c.qty??c.quantity);if(!Number.isFinite(n))return '—';return (unit==='PCS'?Math.trunc(n).toLocaleString('en-IN'):n.toLocaleString('en-IN',{maximumFractionDigits:3}))+' '+unit}
function workType(c){const exact=String(c.work_category||'').toUpperCase();if(exact==='MISSING_CLAIM')return'MISSING';if(['READY_TO_ASSIGN','READY_TO_SUBMIT','ALTER','RECTIFICATION','DAMAGE','MISSING'].includes(exact))return exact;const x=[c.card_type,c.source_module,c.source_event_type,c.source_status,c.message].join(' ').toUpperCase();if(/MISSING_CLAIM|MISSING [0-9.]+ PCS|RECOVERY \/ SHORT/.test(x))return'MISSING';if(/RECTIF/.test(x))return'RECTIFICATION';if(/ALTER|REMAKE|RECEIVE_FROM_MASTER|DELIVER_TO_KARIGAR|KARIGAR_SUBMIT_GOOD|LM_ACCEPT/.test(x))return'ALTER';if(/DAMAGE|PARTIAL_GR|FULL_GR/.test(x))return'DAMAGE';return'READY_TO_SUBMIT'}
function cuttingContext(){return S.active?.id==='CUTTING'||S.active?.parentDepartment==='CUTTING'}
function upmContext(){const d=String(S.active?.parentDepartment||S.active?.id||'').toUpperCase();return ['PRINTING','STICKER','METAL_ID','STITCHING','OVERLOCK','FOLDING','KAAJ_BUTTON','TEAK_TANKI','THREAD_CUT','QC','PRESS','PACKING'].includes(d)}
function allowedWorkFilters(rows=[]){if(cuttingContext())return['READY_TO_SUBMIT','DAMAGE'];if(upmContext())return['READY_TO_SUBMIT','ALTER','RECTIFICATION','MISSING'];return['READY_TO_SUBMIT',...['ALTER','RECTIFICATION','MISSING','DAMAGE'].filter(k=>rows.some(c=>workType(c)===k))]}
function filterWorking(rows){if(!['WORKING','CLOSE'].includes(S.status))return rows;const allowed=allowedWorkFilters(rows),exact=S.search&&rows.find(directSearchMatch);if(exact&&allowed.includes(workType(exact)))S.workFilter=workType(exact);if(!allowed.includes(S.workFilter)||!rows.some(c=>workType(c)===S.workFilter))S.workFilter=allowed.find(k=>rows.some(c=>workType(c)===k))||allowed[0]||'READY_TO_SUBMIT';return rows.filter(c=>workType(c)===S.workFilter)}
function syncWorkFilters(rows=[]){const box=$('workFilters');if(!box)return;box.hidden=!['WORKING','CLOSE'].includes(S.status);const allowed=allowedWorkFilters(rows),regular=cuttingContext()?(S.status==='CLOSE'?'WORK':'LOT'):(S.status==='CLOSE'?'SUBMITTED':'SUBMIT'),labels={READY_TO_SUBMIT:regular,ALTER:'ALTER',RECTIFICATION:'RECTIFY',MISSING:'SHORT / EXCESS',DAMAGE:'DAMAGE / GR'};box.querySelectorAll('[data-work-filter]').forEach(b=>{const key=b.dataset.workFilter,count=rows.filter(c=>workType(c)===key).length;b.hidden=!allowed.includes(key);b.textContent=(labels[key]||key)+' '+count;b.classList.toggle('on',key===S.workFilter)})}
