function changeStatus(status){S.searchAutoSelect=false;S.searchFocusPending=!!S.search;if(status===S.status){focusSearchCard(true,true);return}S.searchFocusIndex=-1;const previous=S.status;history.replaceState({...((history.state)||{view:'inbox'}),status:previous},'',viewUrl(previous));S.status=status;history.pushState({...((history.state)||{view:'inbox'}),status},'',viewUrl(status));syncStatusButtons();renderActive();load(true)}
