function openDivision(gi,push=true){$('drawer').hidden=true;const g=MODULES[gi];if(g.title==='Real Chat Directory')return inbox();S.active={kind:'division',id:String(gi)};$('rows').innerHTML='<h3>'+safe(g.title.toUpperCase())+'</h3>'+g.items.map((x,i)=>'<button class="row" data-module-row="'+i+'"><i>💬</i><span><b>'+safe(x[0])+'</b><small>Module group and relevant personal messages</small></span><strong class="go">›</strong></button>').join('');$('chat').hidden=true;$('inbox').hidden=false;document.querySelectorAll('[data-module-row]').forEach(b=>b.onclick=()=>openWorkflow(gi,Number(b.dataset.moduleRow)));if(push)history.pushState({view:'division',id:String(gi)},'')}
