async function openMembershipAdmin(initialDepartment){if(!membershipAdminRole())return alert('Admin permission required.');const back=document.createElement('div');back.className='vendor-popup';back.innerHTML='<section><header><b>MANAGE DEPARTMENT STAFF</b><button type="button" data-close>×</button></header><p data-state>Staff roster loading…</p><label>Search staff<input data-member-search type="search" placeholder="Name / worker code"></label><label>Worker<select data-worker style="width:100%;margin-top:5px;padding:11px;border-radius:10px;background:#07131f;color:#fff"></select></label><label>Add / Active type<select data-scope style="width:100%;margin-top:5px;padding:11px;border-radius:10px;background:#07131f;color:#fff"><option value="DEPARTMENT">Department worker</option><option value="GLOBAL_WORKER">Global worker</option><option value="MULTI_DEPARTMENT">Multi-department worker</option></select></label><div class="membership-depts" data-departments>'+membershipDepartmentOptions(initialDepartment)+'</div><label>Reason<input data-reason placeholder="Reason / note"></label><footer><button type="button" data-save="ADD">ADD</button><button type="button" data-save="ACTIVE">ACTIVE</button></footer><h3>CURRENT MEMBERSHIP</h3><div class="member-admin-list" data-list></div></section>';document.body.appendChild(back);const close=()=>back.remove(),state=back.querySelector('[data-state]'),worker=back.querySelector('[data-worker]'),scope=back.querySelector('[data-scope]'),search=back.querySelector('[data-member-search]'),list=back.querySelector('[data-list]');back.querySelector('[data-close]').onclick=close;back.onclick=e=>{if(e.target===back)close()};let roster=[];const render=()=>{const q=search.value.trim().toLowerCase();list.innerHTML=roster.filter(x=>!q||[x.worker_name,x.worker_code,x.role_code].join(' ').toLowerCase().includes(q)).map(x=>{const memberships=arr(x.memberships),active=memberships.filter(m=>m.is_active).map(m=>m.department_code),manual=x.manual_global_inactive||memberships.some(m=>m.manual_lock);return '<article class="member-admin-row"><div><b>'+safe(x.worker_name)+'</b><em class="side '+(manual?'':'staff')+'">'+(manual?'INACTIVE':active.length?'ACTIVE':'AUTO INACTIVE')+'</em></div><small>'+safe(x.worker_code||x.role_code||'Worker')+' · '+safe(active.join(', ')||'No active group')+'</small><div class="member-admin-actions"><button data-pick="'+safe(x.worker_id)+'">SELECT</button><button data-member-action="INACTIVE" data-worker-id="'+safe(x.worker_id)+'">INACTIVE</button><button data-member-action="REMOVE" data-worker-id="'+safe(x.worker_id)+'">REMOVE</button></div></article>'}).join('')||'<div class="empty">No matching worker.</div>';list.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{worker.value=b.dataset.pick;worker.scrollIntoView({behavior:'smooth',block:'center'})});list.querySelectorAll('[data-member-action]').forEach(b=>b.onclick=()=>run(b.dataset.memberAction,b.dataset.workerId,'ALL_RELEVANT'))};const chosenDepartments=()=>[...back.querySelectorAll('[data-departments] input:checked')].map(x=>x.value),run=async(action,workerId,forcedScope)=>{if(!workerId)return alert('Worker select करें।');const useScope=forcedScope||scope.value,depts=chosenDepartments(),reason=back.querySelector('[data-reason]').value.trim();if(action==='INACTIVE'||action==='REMOVE'){if(!confirm(action+' करने पर worker सभी relevant groups से inactive होगा। Continue?'))return}state.textContent='Saving '+action+'…';try{await rpc('rr_real_chat_membership_admin_v136',{p_worker_id:workerId,p_action:action,p_scope:useScope,p_department_codes:depts,p_reason:reason||null});state.textContent='✓ '+action+' complete';await load(false);const fresh=await rpc('rr_real_chat_membership_roster_v136');roster=arr(fresh.workers);render()}catch(e){state.textContent=err(e)}};back.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>run(b.dataset.save,worker.value));scope.onchange=()=>{back.querySelector('[data-departments]').hidden=scope.value==='GLOBAL_WORKER'};search.oninput=render;try{const data=await rpc('rr_real_chat_membership_roster_v136');roster=arr(data.workers);worker.innerHTML='<option value="">Select worker</option>'+roster.map(x=>'<option value="'+safe(x.worker_id)+'">'+safe(x.worker_name)+' · '+safe(x.worker_code||x.role_code||'')+'</option>').join('');state.textContent='Manual inactive सभी relevant groups पर लागू होगा। 6 दिन no-working पर auto inactive होगा।';render()}catch(e){state.textContent=err(e)}}
function openDepartment(id,push=true){S.active={kind:'department',id};const d=S.departments.find(x=>x.department_code===id);if(!d)return inbox();$('chatName').textContent=d.department_name+' Department';$('kind').textContent='DEPARTMENT DIRECTORY';$('manageStaffAction').hidden=!membershipAdminRole();$('manageStaffAction').onclick=()=>openMembershipAdmin(id);let h='<button class="row group-entry" data-dept-group="'+safe(id)+'"><i>💬</i><span><b>'+safe(d.department_name)+' Group Chat</b><small>'+countFor(d)+' mapped '+S.status.toLowerCase()+' updates</small></span><strong class="go">›</strong></button><h3>WORKER SIDE · '+Number(d.worker_count||0)+'</h3>';h+=arr(d.workers).map(x=>memberRow(x,'WORKER')).join('')||'<div class="empty">No home worker mapped.</div>';h+='<h3>REDZED STAFF SIDE · '+Number(d.staff_count||0)+'</h3>'+(arr(d.staff).map(x=>memberRow(x,'STAFF')).join('')||'<div class="empty">No RedZed staff mapped.</div>');$('messages').innerHTML=h;$('inbox').hidden=true;$('chat').hidden=false;document.querySelector('[data-dept-group]').onclick=()=>openChat('group',id);document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>openChat('person',b.dataset.person,true,id));if(push)history.pushState({view:'department',department:id},'')}
